function friendBonusRank(rows,value){if(!rows.length)return{leaders:[],points:0,score:0};const score=Math.max(...rows.map(r=>Number(value(r))||0)),leaders=rows.filter(r=>(Number(value(r))||0)===score).map(r=>r.id);return{leaders,points:leaders.length>1?50:100,score}}
function claimFriendBonus(kind,ranking){if(!live||!ranking.leaders.includes(live.selfId))return 0;profile.liveBonusClaims??={};const key=live.code+':'+kind;if(profile.liveBonusClaims[key])return 0;profile.liveBonusClaims[key]={points:ranking.points,time:Date.now()};profile.liveBonusPoints=(profile.liveBonusPoints||0)+ranking.points;profile.coins+=ranking.points;const entries=Object.entries(profile.liveBonusClaims).sort((a,b)=>b[1].time-a[1].time);profile.liveBonusClaims=Object.fromEntries(entries.slice(0,300));save();return ranking.points}
const rankedLiveBegin=beginLiveBattle;beginLiveBattle=function(){if(live){const participants=live.players.filter(p=>p.state?.ready),ranking=friendBonusRank(participants,p=>p.state.right);live.quizRanking={...ranking,rows:participants.map(p=>({id:p.id,name:p.name,score:p.state.right}))};claimFriendBonus('quiz',ranking)}rankedLiveBegin();if(live)for(const p of Object.values(live.units))p.defeats??=0};
const rankedLiveResults=showLiveResults;showLiveResults=function(win){if(!live||live.ended)return;const session=live,units=Object.values(live.units),ranking=friendBonusRank(units,p=>p.defeats||0);if(win)claimFriendBonus('battle',ranking);rankedLiveResults(win);const quizRank=session.quizRanking;const table=(title,rows,rank,allow=true)=>`<section class="friend-scoreboard"><h3>${title}</h3><div>${rows.map(p=>{const top=allow&&rank.leaders.includes(p.id);return `<div class="friend-score-row"><b>${safeText(p.name)}${p.id===session.selfId?' · YOU':''}</b><span>${p.score}</span><strong>${top?'+'+rank.points+' BONUS':'+0'}</strong></div>`}).join('')}</div></section>`;document.querySelector('.results')?.insertAdjacentHTML('beforeend',`${quizRank?table('Quiz · correct answers / 10',quizRank.rows,quizRank):''}${table('Battle · bots defeated',units.map(p=>({id:p.id,name:p.name,score:p.defeats||0})),ranking,win)}<p class="notice">Unique winner: 100 bonus points. Tied leaders: 50 points each. Each bonus point also earns one credit. Battle bonuses require a successful team clear. Your bonus is saved once per round.</p>`)};
const bonusLiveHub=liveHub;liveHub=function(...args){bonusLiveHub(...args);document.querySelector('#modal-content')?.insertAdjacentHTML('beforeend','<p class="notice">FRIEND RIVALRY · Quiz: most correct answers. Battle: most bot defeats on a team clear. Winner +100 points; tied leaders +50 each. Solo boost purchases are disabled.</p>')};

const quizBonusLobby=drawLiveLobby;drawLiveLobby=function(){if(live?.phase==='quiz'){const rows=live.players.filter(p=>p.connected);if(rows.length>=2&&rows.every(p=>p.state?.ready)){const rank=friendBonusRank(rows,p=>p.state.right);live.quizRanking={...rank,rows:rows.map(p=>({id:p.id,name:p.name,score:p.state.right}))};claimFriendBonus('quiz',rank)}}quizBonusLobby();if(live?.quizRanking&&!document.querySelector('#quiz-bonus-summary')){const own=profile.liveBonusClaims?.[live.code+':quiz']?.points||0;document.querySelector('.live-roster')?.insertAdjacentHTML('afterend','<p class="notice" id="quiz-bonus-summary">Quiz complete · Your friend bonus: +'+own+' points. Quiz winner +100; tied leaders +50 each.</p>')}};
